ALTER TABLE organizations ADD CONSTRAINT organizations_id_scope UNIQUE (id);
ALTER TABLE businesses ADD CONSTRAINT businesses_org_id_scope UNIQUE (organization_id, id);
ALTER TABLE business_offerings ADD CONSTRAINT offerings_org_business_scope UNIQUE (business_id, id);
CREATE TABLE IF NOT EXISTS visitor_identities (id uuid PRIMARY KEY, organization_id uuid NOT NULL, business_id uuid NOT NULL, status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','anonymized')), created_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(), retention_expires_at timestamptz NOT NULL, UNIQUE (organization_id, business_id, id), FOREIGN KEY (organization_id, business_id) REFERENCES businesses(organization_id, id));
CREATE TABLE IF NOT EXISTS visitor_sessions (id uuid PRIMARY KEY, organization_id uuid NOT NULL, business_id uuid NOT NULL, visitor_identity_id uuid NOT NULL, status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','ended','expired')), started_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(), ended_at timestamptz, UNIQUE (organization_id, business_id, id), FOREIGN KEY (organization_id, business_id, visitor_identity_id) REFERENCES visitor_identities(organization_id, business_id, id));
CREATE TABLE IF NOT EXISTS visitor_observations (id uuid PRIMARY KEY, organization_id uuid NOT NULL, business_id uuid NOT NULL, visitor_identity_id uuid NOT NULL, session_id uuid NOT NULL, kind text NOT NULL, value jsonb NOT NULL, idempotency_key text NOT NULL, observed_at timestamptz NOT NULL, recorded_at timestamptz NOT NULL DEFAULT now(), source_type text NOT NULL, source_reference text NOT NULL, correction_of_observation_id uuid, UNIQUE (organization_id, visitor_identity_id, idempotency_key), FOREIGN KEY (organization_id, business_id, visitor_identity_id) REFERENCES visitor_identities(organization_id, business_id, id), FOREIGN KEY (organization_id, business_id, session_id) REFERENCES visitor_sessions(organization_id, business_id, id), FOREIGN KEY (correction_of_observation_id) REFERENCES visitor_observations(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS visitor_state_revisions (id uuid PRIMARY KEY, organization_id uuid NOT NULL, business_id uuid NOT NULL, visitor_identity_id uuid NOT NULL, version bigint NOT NULL CHECK (version >= 0), state jsonb NOT NULL, derived_from_revision_id uuid, accepted_observation_id uuid, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (visitor_identity_id, version), UNIQUE (organization_id, business_id, id), FOREIGN KEY (organization_id, business_id, visitor_identity_id) REFERENCES visitor_identities(organization_id, business_id, id), FOREIGN KEY (derived_from_revision_id) REFERENCES visitor_state_revisions(id), FOREIGN KEY (accepted_observation_id) REFERENCES visitor_observations(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS visitor_states (visitor_identity_id uuid PRIMARY KEY, organization_id uuid NOT NULL, business_id uuid NOT NULL, current_revision_id uuid NOT NULL, version bigint NOT NULL CHECK (version >= 0), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY (organization_id, business_id, visitor_identity_id) REFERENCES visitor_identities(organization_id, business_id, id), FOREIGN KEY (organization_id, business_id, current_revision_id) REFERENCES visitor_state_revisions(organization_id, business_id, id), UNIQUE (organization_id, business_id, visitor_identity_id, current_revision_id));
CREATE OR REPLACE FUNCTION kablet_visitor_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'visitor history is immutable'; END $$;
DROP TRIGGER IF EXISTS visitor_observations_immutable ON visitor_observations; CREATE TRIGGER visitor_observations_immutable BEFORE UPDATE OR DELETE ON visitor_observations FOR EACH ROW EXECUTE FUNCTION kablet_visitor_immutable();
DROP TRIGGER IF EXISTS visitor_state_revisions_immutable ON visitor_state_revisions; CREATE TRIGGER visitor_state_revisions_immutable BEFORE UPDATE OR DELETE ON visitor_state_revisions FOR EACH ROW EXECUTE FUNCTION kablet_visitor_immutable();
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['visitor_identities','visitor_sessions','visitor_observations','visitor_state_revisions','visitor_states'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t); END LOOP; END $$;
DROP POLICY IF EXISTS visitor_identity_isolation ON visitor_identities; CREATE POLICY visitor_identity_isolation ON visitor_identities USING (organization_id = kablet_current_org()) WITH CHECK (organization_id = kablet_current_org());
DROP POLICY IF EXISTS visitor_session_isolation ON visitor_sessions; CREATE POLICY visitor_session_isolation ON visitor_sessions USING (organization_id = kablet_current_org()) WITH CHECK (organization_id = kablet_current_org());
DROP POLICY IF EXISTS visitor_observation_isolation ON visitor_observations; CREATE POLICY visitor_observation_isolation ON visitor_observations USING (organization_id = kablet_current_org()) WITH CHECK (organization_id = kablet_current_org());
DROP POLICY IF EXISTS visitor_revision_isolation ON visitor_state_revisions; CREATE POLICY visitor_revision_isolation ON visitor_state_revisions USING (organization_id = kablet_current_org()) WITH CHECK (organization_id = kablet_current_org());
DROP POLICY IF EXISTS visitor_state_isolation ON visitor_states; CREATE POLICY visitor_state_isolation ON visitor_states USING (organization_id = kablet_current_org()) WITH CHECK (organization_id = kablet_current_org());
